reverse_morse = {v: k for k, v in morse_code.items()}

def to_morse(text):
    if not text:
        return ""
    if text[0] == ' ' or text[-1] == ' ':
        raise ValueError
    if '  ' in text:
        raise ValueError
    words = text.split(' ')
    for word in words:
        for char in word:
            if char.upper() not in morse_code:
                raise ValueError
    morse_words = []
    for word in words:
        morse_chars = [morse_code[char.upper()] for char in word]
        morse_word = ' '.join(morse_chars)
        morse_words.append(morse_word)
    return ' / '.join(morse_words)

def from_morse(code):
    if not code:
        return ""
    words = code.split(' / ')
    for word in words:
        if not word:
            raise ValueError
    for word in words:
        codes = word.split(' ')
        for c in codes:
            if not c or c not in reverse_morse:
                raise ValueError
    text_words = []
    for word in words:
        codes = word.split(' ')
        chars = [reverse_morse[c] for c in codes]
        text_words.append(''.join(chars))
    return ' '.join(text_words)

