def cents_to_text(cents):
    if type(cents) is not int:
        raise ValueError("Input must be an integer")
    if isinstance(cents, bool):
        raise ValueError("Input must be an integer, not a boolean")

    sign = '-' if cents < 0 else ''
    cents_abs = abs(cents)

    dollars = cents_abs // 100
    cents_part = cents_abs % 100

    if dollars == 0:
        dollar_str = "0"
    else:
        dollar_str = f"{dollars:,}"

    cents_str = f"{cents_part:02d}"
    return f"{sign}{dollar_str}.{cents_str}"

def text_to_cents(text):
    if not isinstance(text, str):
        raise ValueError("Input must be a string")

    if '.' not in text:
        raise ValueError("Missing decimal point")
    parts = text.split('.')
    if len(parts) != 2:
        raise ValueError("Invalid format")
    dollar_part, cents_part = parts

    if len(cents_part) != 2 or not cents_part.isdigit():
        raise ValueError("Invalid cents part")

    sign = 1
    if dollar_part.startswith('-'):
        sign = -1
        dollar_part = dollar_part[1:]
    elif dollar_part.startswith('+'):
        raise ValueError("Invalid '+' sign")

    if not dollar_part:
        raise ValueError("Invalid dollar part")

    s = dollar_part.replace(',', '')
    if s != '0' and (len(s) > 1 and s[0] == '0'):
        raise ValueError("Leading zero in dollar part")
    if not s.isdigit():
        raise ValueError("Invalid dollar part")

    formatted = format(int(s), ',')
    if formatted != dollar_part:
        raise ValueError("Invalid comma placement in dollar part")

    total_dollars = int(s)
    total_cents = total_dollars * 100 + int(cents_part)

    if total_dollars == 0 and sign == -1 and total_cents == 0:
        raise ValueError("Invalid negative zero")

    return sign * total_cents

def cidr_range(text):
    # Validate input
    if not isinstance(text, str):
        raise ValueError

    # Split into IP and CIDR parts
    parts = text.split('/')
    if len(parts) != 2:
        raise ValueError
    ip_str, cidr_str = parts

    # Validate CIDR part
    if not cidr_str.isdigit():
        raise ValueError
    if len(cidr_str) > 1 and cidr_str[0] == '0':
        raise ValueError
    n = int(cidr_str)
    if n < 0 or n > 32:
        raise ValueError

    # Split IP into parts
    octets = ip_str.split('.')
    if len(octets) != 4:
        raise ValueError

    for octet in octets:
        if not octet.isdigit():
            raise ValueError
        if len(octet) > 1 and octet[0] == '0':
            raise ValueError
        num = int(octet)
        if num < 0 or num > 255:
            raise ValueError

    # Convert IP to integer
    ip_int = 0
    for octet in octets:
        ip_int = (ip_int << 8) | int(octet)

    # Compute mask and network address
    if n == 0:
        mask = 0
    else:
        mask = (0xFFFFFFFF << (32 - n)) & 0xFFFFFFFF
    network_int = ip_int & mask

    # Compute broadcast address
    if n == 32:
        broadcast_int = network_int
    else:
        broadcast_int = network_int | ((1 << (32 - n)) - 1)

    # Compute size
    size = 1 << (32 - n)

    # Convert network and broadcast integers to dotted strings
    def int_to_dotted(ip_int):
        octets = []
        for _ in range(4):
            octets.append(str(ip_int & 0xFF))
            ip_int >>= 8
        return '.'.join(octets[::-1])

    first = int_to_dotted(network_int)
    last = int_to_dotted(broadcast_int)

    return (first, last, size)

