    if not isinstance(number, str):
        raise ValueError
    if len(number) < 2:
        raise ValueError
    for c in number:
        if not c.isdigit():
            raise ValueError
    reversed_num = number[::-1]
    total = 0
    for i, c in enumerate(reversed_num):
        digit = int(c)
        if i % 2 == 1:
            doubled = digit * 2
            if doubled > 9:
                doubled -= 9
            total += doubled
        else:
            total += digit
    return total % 10 == 0

