def parse_query(text):
    if not isinstance(text, str):
        raise ValueError("text must be a string")
    if not text:
        return []
    parts = text.split('&')
    allowed_chars = set('abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789-._~')

    def decode(s):
        result = []
        i = 0
        while i < len(s):
            c = s[i]
            if c == '+':
                result.append(' ')
                i += 1
            elif c == '%':
                if i + 2 >= len(s):
                    raise ValueError("Incomplete percent encoding")
                hex_str = s[i+1:i+3]
                if not all(ch in '0123456789abcdefABCDEF' for ch in hex_str):
                    raise ValueError("Invalid percent encoding")
                code = int(hex_str, 16)
                if code > 0x7f:
                    raise ValueError("Character code above 0x7F")
                result.append(chr(code))
                i += 3
            else:
                if c in allowed_chars:
                    result.append(c)
                    i += 1
                else:
                    raise ValueError(f"Invalid character '{c}' in encoded string")
        return ''.join(result)

    result = []
    for part in parts:
        if not part:
            raise ValueError("Empty part in query string")
        if part.count('=') != 1:
            raise ValueError("Part must contain exactly one '='")
        key_part, value_part = part.split('=', 1)
        if not key_part:
            raise ValueError("Key cannot be empty")
        try:
            key = decode(key_part)
            value = decode(value_part)
        except ValueError as e:
            raise ValueError(f"Decoding error: {e}")
        result.append((key, value))
    return result


def build_query(pairs):
    if not isinstance(pairs, (list, tuple)):
        raise ValueError("pairs must be a list or tuple")
    for pair in pairs:
        if not isinstance(pair, tuple) or len(pair) != 2:
            raise ValueError("Each pair must be a tuple of two strings")
        key, value = pair
        if not isinstance(key, str) or not isinstance(value, str):
            raise ValueError("Key and value must be strings")
        if not key:
            raise ValueError("Key cannot be empty")
        for c in key + value:
            if not c.isascii():
                raise ValueError("Non-ASCII character found")

    def encode(s):
        allowed = set('abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789-._~')
        result = []
        for c in s:
            if c in allowed:
                result.append(c)
            elif c == ' ':
                result.append('+')
            else:
                result.append(f"%{ord(c):02X}")
        return ''.join(result)

    encoded_pairs = []
    for key, value in pairs:
        encoded_key = encode(key)
        encoded_value = encode(value)
        encoded_pairs.append(f"{encoded_key}={encoded_value}")
    return '&'.join(encoded_pairs)

def persistence(n):
    if not isinstance(n, int) or isinstance(n, bool):
        raise ValueError
    if n < 0:
        raise ValueError

    def sum_digits(x):
        s = 0
        while x > 0:
            s += x % 10
            x = x // 10
        return s

    def product_digits(x):
        p = 1
        while x > 0:
            digit = x % 10
            if digit == 0:
                return 0
            p *= digit
            x = x // 10
        return p

    def count_steps(func):
        count = 0
        current = n
        while current >= 10:
            current = func(current)
            count += 1
        return count

    additive = count_steps(sum_digits)
    multiplicative = count_steps(product_digits)
    return (additive, multiplicative)

def digital_root(n):
    if not isinstance(n, int) or isinstance(n, bool):
