    remainder = n % 9
    return 9 if remainder == 0 else remainder

def phi(n):
    if not isinstance(n, int) or isinstance(n, bool) or n < 1 or n > 10**12:
        raise ValueError
    if n == 1:
        return 1
    result = n
    i = 2
    while i * i <= n:
        if n % i == 0:
            while n % i == 0:
                n = n // i
            result = result // i * (i - 1)
        i += 1
    if n > 1:
        result = result // n * (n - 1)
    return result

def totient_sum(limit):
    if not isinstance(limit, int) or isinstance(limit, bool) or limit < 1 or limit > 10**5:
        raise ValueError
    t = list(range(limit + 1))
    for p in range(2, limit + 1):
        if t[p] == p:  # p is a prime
            for m in range(p, limit + 1, p):
                t[m] -= t[m] // p
    return sum(t[1:limit + 1])

def sieve(n):
    """Generate a list of booleans where sieve[i] is True if i is a prime."""
    if n < 2:
        return []
    sieve_list = [True] * (n + 1)
    sieve_list[0] = sieve_list[1] = False
    for i in range(2, int(n ** 0.5) + 1):
        if sieve_list[i]:
            sieve_list[i*i : n+1 : i] = [False] * len(sieve_list[i*i : n+1 : i])
    return sieve_list

def goldbach_pairs(n):
    if not isinstance(n, int) or isinstance(n, bool):
        raise ValueError
    if n < 4 or n > 1000000 or n % 2 != 0:
        raise ValueError
    sieve_list = sieve(n)
    count = 0
    for p in range(2, n // 2 + 1):
        q = n - p
        if sieve_list[p] and sieve_list[q]:
            count += 1
    return count

