def primitive_triples(limit):
    if not isinstance(limit, int) or type(limit) is bool or limit < 0 or limit > 100000:
        raise ValueError
    if limit < 5:
        return []
    m_max = int(math.sqrt(limit - 1))
    triples = []
    for m in range(2, m_max + 1):
        for k in range(1, m):
            if math.gcd(m, k) == 1 and (m - k) % 2 == 1:
                a = m * m - k * k
                b = 2 * m * k
                if a > b:
                    a, b = b, a
                c = m * m + k * k
                if c > limit:
                    continue
                triples.append((a, b, c))
    triples.sort(key=lambda x: (x[2], x[0]))
    return triples

def count_triples(limit):
    if not isinstance(limit, int) or type(limit) is bool or limit < 0 or limit > 100000:
        raise ValueError
    return len(primitive_triples(limit))

