_happy_cache = {}

def is_happy(n):
    if not isinstance(n, int) or n < 1 or isinstance(n, bool):
        raise ValueError
    if n in _happy_cache:
        return _happy_cache[n]
    current = n
    while True:
        if current == 1:
            _happy_cache[n] = True
            return True
        if current == 4:
            _happy_cache[n] = False
            return False
        sum_sq = 0
        while current > 0:
            digit = current % 10
            sum_sq += digit ** 2
            current = current // 10
        current = sum_sq

def happy_count(limit):
    if not hasattr(happy_count, '_happy_numbers'):
        happy_count._happy_numbers = []
        for n in range(1, 100001):
            if is_happy(n):
                happy_count._happy_numbers.append(n)
    if type(limit) is not int or limit < 0 or limit > 100000 or isinstance(limit, bool):
        raise ValueError
    return bisect.bisect_right(happy_count._happy_numbers, limit)

import math

def egyptian(p, q):
    if type(p) is not int or type(q) is not int:
        raise ValueError
    if isinstance(p, bool) or isinstance(q, bool):
        raise ValueError
    if not (1 <= p < q <= 200):
        raise ValueError

    denominators = []
    current_num = p
    current_den = q

    while current_num != 0:
        n = (current_den + current_num - 1) // current_num
        denominators.append(n)
        new_num = current_num * n - current_den
        new_den = current_den * n
        g = math.gcd(new_num, new_den)
        current_num = new_num // g
        current_den = new_den // g

    return denominators

def unit_sum(denominators):
    if not isinstance(denominators, (list, tuple)):
        raise ValueError

    for d in denominators:
        if type(d) is not int or isinstance(d, bool) or d < 1:
            raise ValueError

    sum_num = 0
    sum_den = 1

    for d in denominators:
        new_num = sum_num * d + sum_den
        new_den = sum_den * d
        g = math.gcd(new_num, new_den)
        sum_num = new_num // g
        sum_den = new_den // g

    if sum_num == 0:
        return (0, 1)
    else:
        return (sum_num, sum_den)

