def closest_pair(points):
    # Input validation
    if not isinstance(points, (list, tuple)):
        raise ValueError
    n = len(points)
    if n < 2 or n > 500:
        raise ValueError
    for p in points:
        if not isinstance(p, (list, tuple)):
            raise ValueError
        if len(p) != 2:
            raise ValueError
        x, y = p[0], p[1]
        if type(x) is not int or type(y) is not int:
            raise ValueError
        if not (-10**6 <= x <= 10**6) or not (-10**6 <= y <= 10**6):
            raise ValueError

    # Initialize variables to track the closest pair
    min_d2 = float('inf')
    best_i = -1
    best_j = -1

    # Iterate through all pairs of points
    for i in range(n):
        x1, y1 = points[i][0], points[i][1]
        for j in range(i + 1, n):
            x2, y2 = points[j][0], points[j][1]
            dx = x1 - x2
            dy = y1 - y2
            d2 = dx * dx + dy * dy
            # Early exit if the smallest possible distance is found
            if d2 == 0:
                return (d2, i, j)
            # Update the closest pair if a smaller distance is found
            if d2 < min_d2:
                min_d2 = d2
                best_i = i
                best_j = j
            elif d2 == min_d2:
                # Check if the current pair has a smaller index
                if i < best_i or (i == best_i and j < best_j):
                    best_i = i
                    best_j = j

    return (min_d2, best_i, best_j)

