        in_degree[b] += 1

    # Check degree conditions
    start_vertex = None
    end_vertex = None
    for vertex in range(n):
        diff = out_degree.get(vertex, 0) - in_degree.get(vertex, 0)
        if diff == 1:
            if start_vertex is not None:
                return None
            start_vertex = vertex
        elif diff == -1:
            if end_vertex is not None:
                return None
            end_vertex = vertex
        elif diff != 0:
