        raise ValueError
    for edge in edges:
        if not isinstance(edge, (list, tuple)) or len(edge) != 2:
            raise ValueError
        a, b = edge
        if not isinstance(a, int) or not isinstance(b, int):
            raise ValueError
        if a < 0 or a >= n or b < 0 or b >= n:
            raise ValueError

    # Build adjacency list
    adj = [[] for _ in range(n)]
    for a, b in edges:
        adj[a].append(b)
        adj[b].append(a)

    # Function to compute the farthest node and distance from start
    def bfs(start):
        from collections import deque
        visited = [False] * n
        distance = [-1] * n
        q = deque()
        q.append(start)
        visited[start] = True
        distance[start] = 0
        max_dist = 0
        far_node = start
        while q:
            current = q.popleft()
            for neighbor in adj[current]:
                if not visited[neighbor]:
                    visited[neighbor] = True
                    distance[neighbor] = distance[current] + 1
                    q.append(neighbor)
                    if distance[neighbor] > max_dist:
                        max_dist = distance[neighbor]
                        far_node = neighbor
        return far_node, distance

    # Find the diameter using BFS
    u = bfs(0)[0]
    v, _ = bfs(u)
    # Perform BFS again to get the distance from u to all nodes
    _, distance = bfs(u)

    # Find the radius and centers
    radius = 0
    centers = []
    for i in range(n):
        if distance[i] > radius:
            radius = distance[i]
            centers = [i]
        elif distance[i] == radius:
            centers.append(i)

    # Sort the centers
    centers.sort()

    return (centers, radius)

