            raise ValueError
        if a < 0 or a >= n or b < 0 or b >= n:
            raise ValueError
        if a == b:
            raise ValueError

    # Build adjacency list
    adj = [[] for _ in range(n)]
    for a, b in edges:
        adj[a].append(b)
        adj[b].append(a)

    from collections import deque

    def bfs(start):
        visited = {start: 0}
        q = deque([start])
        parent = {start: None}
        max_dist = 0
        far_node = start
        while q:
            current = q.popleft()
            for neighbor in adj[current]:
                if neighbor not in visited:
                    visited[neighbor] = visited[current] + 1
                    parent[neighbor] = current
                    q.append(neighbor)
                    if visited[neighbor] > max_dist:
                        max_dist = visited[neighbor]
                        far_node = neighbor
        return max_dist, far_node, parent

    # First BFS from node 0 to find u
    _, u, _ = bfs(0)

    # Second BFS from u to find v and get parent pointers
    _, v, parent = bfs(u)

    # Reconstruct the path from u to v
    path = []
    current = v
    while current is not None:
        path.append(current)
        current = parent.get(current)
    path = path[::-1]  # Reverse to get the path from u to v

    # Calculate D and radius
    D = len(path) - 1
    radius = (D + 1) // 2

    # Determine the centers
    if D % 2 == 0:
        mid = D // 2
        centers = [path[mid]]
    else:
        mid1 = (D - 1) // 2
        mid2 = mid1 + 1
        centers = [path[mid1], path[mid2]]

    # Sort the centers
    centers.sort()

