        raise ValueError
    if len(edges) != n - 1:
        raise ValueError
    for edge in edges:
        if not isinstance(edge, (list, tuple)) or len(edge) != 2:
            raise ValueError
        a, b = edge
        if not (isinstance(a, int) and not isinstance(a, bool)) or a < 0 or a >= n:
            raise ValueError
        if not (isinstance(b, int) and not isinstance(b, bool)) or b < 0 or b >= n:
            raise ValueError

    # Build adjacency list
    adj = [[] for _ in range(n)]
    for a, b in edges:
        adj[a].append(b)
        adj[b].append(a)

    if n == 1:
        return ([0], 0)

    def bfs(start):
        visited = [False] * n
        distance = [-1] * n
        parent = [-1] * n
        q = deque([start])
        visited[start] = True
        distance[start] = 0
        while q:
            current = q.popleft()
            for neighbor in adj[current]:
                if not visited[neighbor]:
                    visited[neighbor] = True
                    distance[neighbor] = distance[current] + 1
                    parent[neighbor] = current
                    q.append(neighbor)
        max_dist = max(distance)
        farthest = distance.index(max_dist)
        return farthest, parent, distance

    u, _, _ = bfs(0)
    v, parent, _ = bfs(u)

    # Reconstruct the path from u to v
    path = []
    current = v
    while current != u:
        path.append(current)
        current = parent[current]
    path.append(u)
    path = path[::-1]  # Reverse to get the path from u to v

    D = len(path) - 1
    radius = (D + 1) // 2

    if D % 2 == 0:
        mid = D // 2
        centers = [path[mid]]
    else:
        mid = D // 2
        centers = [path[mid], path[mid + 1]]

    centers.sort()
    return (centers, radius)

