        raise ValueError
    if not isinstance(requests, (list, tuple)):
        raise ValueError
    for floor in requests:
        if not isinstance(floor, int) or floor < 0 or floor > 1000:
            raise ValueError

    # Process requests
    unique_requests = list(set(requests))
