def josephus(n, k):
    if type(n) is not int or type(k) is not int:
        raise ValueError
    if n < 1 or k < 1:
        raise ValueError
    if n > 5000 or k > 1000000:
        raise ValueError
    people = list(range(1, n + 1))
    result = []
    i = 0
    while people:
        index = (i + k - 1) % len(people)
        eliminated = people.pop(index)
        result.append(eliminated)
        if people:
            i = index % len(people)
    return result

def josephus_survivor(n, k):
    if type(n) is not int or type(k) is not int:
        raise ValueError
    if n < 1 or k < 1:
        raise ValueError
    if n > 1000000 or k > 1000000:
        raise ValueError
    if n == 1:
        return 1
    res = 0
    for m in range(2, n + 1):
        res = (res + k) % m
    return res + 1

