    for num in nums:
        if not (isinstance(num, int) and not isinstance(num, bool)):
            raise ValueError
        if not (lower <= num <= upper):
            raise ValueError

    # Initialize variables
    prefix_sum = 0
    min_prefix = 0
    min_prefix_index = -1
    best_sum = -float('inf')
    start = 0
    end = 0

    for j in range(len(nums)):
        current_num = nums[j]
        prefix_sum += current_num

        current_sum = prefix_sum - min_prefix

        if current_sum > best_sum:
            best_sum = current_sum
            start = min_prefix_index + 1
            end = j
        elif current_sum == best_sum:
            current_start = min_prefix_index + 1
            if current_start < start:
                start = current_start
                end = j
            elif current_start == start:
                if j < end:
                    end = j

        # Update min_prefix and min_prefix_index
        if prefix_sum < min_prefix:
            min_prefix = prefix_sum
            min_prefix_index = j

