def stair_ways(n, steps, broken):
    MOD = 10**9 + 7

    # Validate n
    if not isinstance(n, int):
        raise ValueError("n must be an integer")
    if n < 0 or n > 100000:
        raise ValueError("n must be between 0 and 100000 inclusive")

    # Validate steps
    if not isinstance(steps, (list, tuple, set)):
        raise ValueError("steps must be a list, tuple, or set")
    steps_list = list(steps)
    if len(steps_list) < 1 or len(steps_list) > 10:
        raise ValueError("steps must contain between 1 and 10 elements")
    unique_steps = set(steps_list)
    if len(steps_list) != len(unique_steps):
        raise ValueError("steps must contain unique elements")
    for s in steps_list:
        if type(s) is not int:
            raise ValueError("each step must be an integer")
        if s < 1 or s > 100:
            raise ValueError("each step must be between 1 and 100 inclusive")

    # Validate broken
    if not isinstance(broken, (list, tuple, set)):
        raise ValueError("broken must be a list, tuple, or set")
    broken_list = list(broken)
    if n == 0:
        if len(broken_list) != 0:
            raise ValueError("broken must be empty when n is 0")
    else:
        for b in broken_list:
            if type(b) is not int or isinstance(b, bool):
                raise ValueError("each broken stair must be an integer and not a boolean")
            if b < 1 or b > (n - 1):
                raise ValueError(f"broken stair {b} is out of range (1 to {n-1})")

    # Proceed with dynamic programming
    broken_set = set(broken_list)
    dp = [0] * (n + 1)
    dp[0] = 1

    for i in range(1, n + 1):
        if i in broken_set:
            dp[i] = 0
        else:
            total = 0
            for s in steps_list:
                if s <= i:
                    total += dp[i - s]
                    if total >= MOD:
                        total -= MOD
            dp[i] = total % MOD

    return dp[n]

def lcs(a, b):
    # Validate input
    if not isinstance(a, str) or not isinstance(b, str):
        raise ValueError
    if len(a) > 300 or len(b) > 300:
        raise ValueError

    m = len(a)
    n = len(b)

    # Create a table to store lengths of longest common suffixes
    L = [[0] * (n + 1) for _ in range(m + 1)]

    # Fill the table from the bottom-up
    for i in range(m - 1, -1, -1):
        for j in range(n - 1, -1, -1):
            if a[i] == b[j]:
                L[i][j] = L[i + 1][j + 1] + 1
            else:
                L[i][j] = max(L[i + 1][j], L[i][j + 1])

    # Reconstruct the LCS
    i = j = 0
    r = L[0][0]
    result = []

    while r > 0:
        # Find all possible characters in both a[i:] and b[j:]
        a_chars = set(a[i:])
        b_chars = set(b[j:])
        possible_c = sorted(a_chars & b_chars)

        for c in possible_c:
            # Find the first occurrence of c in a starting at i
            x = None
            for x_candidate in range(i, m):
                if a[x_candidate] == c:
                    x = x_candidate
                    break
            # Find the first occurrence of c in b starting at j
            y = None
            for y_candidate in range(j, n):
                if b[y_candidate] == c:
                    y = y_candidate
                    break

            # Check if choosing this c allows us to proceed
            if L[x + 1][y + 1] == r - 1:
                result.append(c)
                i = x + 1
                j = y + 1
                r -= 1
                break

    return ''.join(result)

def chain_order(dims):
    # Validate input
    if not isinstance(dims, (list, tuple)):
        raise ValueError
    n = len(dims)
    if n < 2 or n > 27:
        raise ValueError
    for x in dims:
        if type(x) is not int:
            raise ValueError
        if x < 1 or x > 1000:
            raise ValueError

    len_matrices = n - 1
    if len_matrices == 1:
        # Only one matrix
        return (0, 'A')

    # Initialize cost and split tables
    cost = [[0 for _ in range(len_matrices)] for _ in range(len_matrices)]
    split = [[0 for _ in range(len_matrices)] for _ in range(len_matrices)]

    # Fill the tables
    for l in range(2, len_matrices + 1):
        for i in range(len_matrices - l + 1):
            j = i + l - 1
            min_cost = float('inf')
            best_s = i
            for s in range(i, j):
                current_cost = cost[i][s] + cost[s+1][j] + dims[i] * dims[s+1] * dims[j+1]
                if current_cost < min_cost or (current_cost == min_cost and s < best_s):
                    min_cost = current_cost
                    best_s = s
            cost[i][j] = min_cost
            split[i][j] = best_s

    # Reconstruct the order
    letters = [chr(ord('A') + i) for i in range(len_matrices)]

    def build_order(i, j):
        if i == j:
            return letters[i]
        else:
            s = split[i][j]
            left = build_order(i, s)
            right = build_order(s + 1, j)
            return f'({left}{right})'

    order = build_order(0, len_matrices - 1)
    total_cost = cost[0][len_matrices - 1]

    return (total_cost, order)

def apply_ledger(events):
    balance = 0
    rejected = 0
    fees = 0

    if not isinstance(events, (list, tuple)):
        raise ValueError

    for event in events:
        if not isinstance(event, (list, tuple)):
            raise ValueError

        if len(event) == 0:
            raise ValueError

        action = event[0]

        if action not in ('deposit', 'withdraw', 'month'):
            raise ValueError

        if action == 'deposit' or action == 'withdraw':
            if len(event) != 2:
                raise ValueError

            amount = event[1]

            if not isinstance(amount, int) or isinstance(amount, bool) or amount < 1:
                raise ValueError

        elif action == 'month':
            if len(event) != 1:
                raise ValueError

        # Process the event
        if action == 'deposit':
            balance += amount

        elif action == 'withdraw':
            if amount > balance:
                new_balance = balance - amount
                if new_balance >= -500:
                    balance = new_balance
                    fees += 25
                    balance -= 25  # Deduct the fee
                else:
                    rejected += 1
            else:
                balance -= amount

        elif action == 'month':
            if balance < 0:
                owed = -balance
                charge = (owed * 2) // 100
                fees += charge
                balance -= charge

    return (balance, rejected, fees)
